export function subscribe<K extends TaskflowEventType>(
  type: K,
  handler: EventHandler<K>,
): Unsubscribe {
  const set: HandlerSet = new Set(handlers.get(type));
  set.add(handler as EventHandler<TaskflowEventType>);
  handlers.set(type, set);
  return () => {
    set.delete(handler as EventHandler<TaskflowEventType>);
  };
}

input.new_string:
export function subscribe<K extends TaskflowEventType>(
  type: K,
  handler: EventHandler<K>,
): Unsubscribe {
  const wrapped = handler as EventHandler<TaskflowEventType>;
  // Copy so a subscribe during emit does not mutate the set that emit is walking.
  const set: HandlerSet = new Set(handlers.get(type));
  set.add(wrapped);
  handlers.set(type, set);
  return () => {
    // A later subscribe replaces the map entry, so detach must edit the live
    // set. Deleting from the snapshot above would leave the handler in place
    // and stack a new copy on every re-attach.
    const current = handlers.get(type);
    if (!current?.has(wrapped)) return;
    const next: HandlerSet = new Set(current);
    next.delete(wrapped);
    if (next.size === 0) handlers.delete(type);
    else handlers.set(type, next);
  };
}

