import { subscribe, subscriberCount, emit, resetEventBus } from "./src/lib/event-bus.ts";

function cycle(label: string) {
  const counts = { a: 0, s: 0, u: 0, w: 0, n: 0 };
  const offs = [
    subscribe("issue.created", () => { counts.a++; }),
    subscribe("issue.created", () => { counts.s++; }),
    subscribe("issue.created", () => { counts.u++; }),
    subscribe("issue.created", () => { counts.w++; }),
  ];
  return { counts, offs, label };
}

resetEventBus();
const note = subscribe("issue.created", () => {});
let group = [
  subscribe("issue.created", () => {}),
  subscribe("issue.created", () => {}),
  subscribe("issue.created", () => {}),
  subscribe("issue.created", () => {}),
];
console.log("registered", subscriberCount("issue.created"));
for (const off of group) off();
console.log("detached (note should remain)", subscriberCount("issue.created"));
group = [
  subscribe("issue.created", () => {}),
  subscribe("issue.created", () => {}),
  subscribe("issue.created", () => {}),
  subscribe("issue.created", () => {}),
];
console.log("reattached", subscriberCount("issue.created"));
for (const off of group) off();
group = [
  subscribe("issue.created", () => {}),
  subscribe("issue.created", () => {}),
  subscribe("issue.created", () => {}),
  subscribe("issue.created", () => {}),
];
console.log("second reattach", subscriberCount("issue.created"));
// double register without detach
const extra = subscribe("issue.created", () => {});
console.log("after extra sub", subscriberCount("issue.created"));
extra();
